(function(){
  'use strict';
  const M=window.KbitLayout,KEY='kbit-slot-layout-v1',n=value=>new Intl.NumberFormat('es-PE',{maximumFractionDigits:1}).format(value);
  const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let stored=null;
  try{const raw=localStorage.getItem(KEY);if(raw)stored=M.normalize(JSON.parse(raw));}catch{}
  let draft=stored?{...stored}:M.fromPreset('parallel');
  const equal=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
  const typeName=c=>M.presets.find(p=>p.id===c.geometry).name;
  const zoneName=zone=>({'upper-left':'Superior izq.','upper-right':'Superior der.','lower-left':'Inferior izq.','lower-right':'Inferior der.',left:'Ala izquierda',right:'Ala derecha',base:'Zona principal'}[zone]||zone);
  function fieldText(c){return {aisles:c.geometry==='fishbone'?['Filas por zona','Cuatro zonas; las filas se ajustan al espacio']:c.geometry==='chevron'?['Pasillos por ala','Dos alas a ambos lados de la vía central']:['Pasillos','Filas de acceso · de 1 a 64'],bays:['Estantes por lado',(c.geometry==='flying-v'||c.geometry==='fishbone')?'Máximo por fila; se descuentan los accesos':'Por cada pasillo · de 1 a 100']};}
  function thumbnail(index){return plan(M.fromPreset(M.presets[index].id),null,null,true);}
  function numberField(key,label,help,step=1){const [min,max]=M.limits[key];return '<div class="design-field" data-design-field="'+key+'"><label for="design-'+key+'">'+label+'</label><div class="design-stepper"><button type="button" data-design-step="'+key+'" data-direction="-1" aria-label="Reducir '+label.toLowerCase()+'">−</button><input id="design-'+key+'" name="'+key+'" type="number" min="'+min+'" max="'+max+'" step="'+step+'" value="'+draft[key]+'" inputmode="'+(step===1?'numeric':'decimal')+'" required><button type="button" data-design-step="'+key+'" data-direction="1" aria-label="Aumentar '+label.toLowerCase()+'">+</button></div><small>'+help+'</small></div>';}
  function geometryFields(){return '<div class="design-geometry-fields design-field-grid">'+numberField('vDepth','Profundidad de la V','25–80 % del fondo de almacenaje')+numberField('angle','Ángulo de las filas','30–60 grados desde la horizontal')+'</div><p class="design-geometry-note" id="design-geometry-note"></p>';}
  function preview(){return '<section class="panel design-preview"><div class="design-preview-bar"><div><span class="eyebrow">Vista del espacio</span><h2 id="design-scene-title">Almacén completo</h2></div><div class="scene-view-switch" aria-label="Tipo de vista"><button type="button" data-design-view="3d" aria-pressed="true">3D</button><button type="button" data-design-view="plan" aria-pressed="false">Plano 2D</button></div></div><div class="design-viewport"><div id="design-webgl" class="design-webgl"></div><div id="design-plan" class="design-plan" hidden></div><span class="design-corner-label" id="design-scale-label"></span><div class="design-camera"><button class="btn" type="button" data-design-camera="iso" aria-label="Vista en perspectiva">↗ Perspectiva</button><button class="btn" type="button" data-design-camera="top">↓ Superior</button><button class="btn" type="button" data-design-zoom="1.25" aria-label="Acercar">+</button><button class="btn" type="button" data-design-zoom="0.8" aria-label="Alejar">−</button></div><div class="design-compass" aria-hidden="true">N ↑<br><span>EMPAQUE / SALIDA ↓</span></div></div><div class="design-explore"><label for="design-sector">Explorar sector</label><select id="design-sector" aria-label="Explorar sector"></select><button class="btn btn-plain" type="button" data-design-all>Ver todo</button></div><div class="design-selection"><label for="design-rack">Inspeccionar estante</label><select id="design-rack" aria-label="Inspeccionar estante"></select><p id="design-rack-info">Selecciona un estante para ver sus ubicaciones.</p></div><div class="design-legend"><span><i class="design-legend-rack"></i>Estantería</span><span><i class="design-legend-aisle"></i>Circulación</span><span id="design-view-note"></span></div></section>';}
  function metrics(){return '<div class="design-metrics" aria-live="polite"><div><span>Ubicaciones totales</span><strong id="design-total">—</strong><small id="design-formula"></small></div><div><span>Estantes</span><strong id="design-racks">—</strong><small id="design-stat-aisles"></small></div><div><span>Superficie estimada</span><strong id="design-area">—</strong><small id="design-dimensions"></small></div><div><span>Altura de estantería</span><strong id="design-height">—</strong><small id="design-stat-levels"></small></div></div>';}
  function page(){return '<section id="warehouse-designer"><header class="page-heading"><div><div class="eyebrow">01 / Configura tu espacio</div><h1>Tu almacén empieza aquí.</h1><p>Elige su geometría, ajusta las medidas y recórrela antes de guardarla.</p></div><div class="actions"><span class="pill" id="design-save-state">Borrador</span><button type="button" class="btn btn-primary" data-design-save>Guardar diseño</button></div></header><div class="design-template-heading"><h2>Elige el tipo de almacén</h2><span>Mismas medidas y controles; cuatro geometrías.</span></div><div class="design-templates">'+M.presets.map((p,i)=>'<button type="button" class="design-template" data-design-template="'+p.id+'" aria-pressed="'+(draft.template===p.id)+'">'+thumbnail(i)+'<span><small>'+p.tag+'</small><strong>'+p.name+'</strong><span>'+p.description+'</span></span><b class="design-template-check" aria-hidden="true">↗</b></button>').join('')+'</div>'+metrics()+'<div class="design-layout">'+preview()+'<aside class="design-config panel"><div class="panel-head"><h2>Ajusta tu almacén</h2><span class="pill" id="design-config-label">'+M.presets.find(p=>p.id===draft.template).name+'</span></div><form id="design-form" novalidate><div class="design-name"><label for="design-name">Nombre del almacén</label><input id="design-name" name="name" maxlength="60" value="'+esc(draft.name)+'" placeholder="Ej. Centro de distribución Lima"></div><div class="design-field-grid">'+numberField('aisles','Pasillos','De 1 a 64')+numberField('bays','Estantes por lado','Por cada pasillo · de 1 a 100')+numberField('levels','Niveles por estante','Alturas de almacenaje · de 1 a 12')+numberField('positions','Huecos por nivel','Ubicaciones por estante · de 1 a 6')+'</div>'+geometryFields()+'<fieldset class="design-sides"><legend>Estanterías del pasillo</legend><label><input type="radio" name="sides" value="2" '+(draft.sides===2?'checked':'')+'> Ambos lados</label><label><input type="radio" name="sides" value="1" '+(draft.sides===1?'checked':'')+'> Un lado</label></fieldset><details class="design-dimensions"><summary>Medidas y accesos <span>metros</span></summary><div class="design-field-grid">'+numberField('aisleWidth','Ancho de pasillo','Espacio libre de circulación',.1)+numberField('bayWidth','Ancho del estante','Frente de cada módulo',.1)+numberField('rackDepth','Fondo del estante','Profundidad de almacenaje',.1)+numberField('levelHeight','Altura entre niveles','Distancia vertical',.05)+numberField('crossEvery','Acceso cada','Cada X módulos deja 3 m libres')+'</div></details><p class="design-error" id="design-error" role="alert" hidden></p><div class="design-config-foot"><span class="small muted">Los cambios se ven al instante. Guardar aplica el diseño a Mi almacén.</span><button class="btn btn-primary btn-full" type="submit">Guardar diseño</button><button class="btn btn-full" type="button" data-design-restore '+(!stored?'disabled':'')+'>Volver al diseño guardado</button></div></form></aside></div><div class="design-footnote"><p><b>De un pasillo a muchos sectores.</b> En almacenes grandes, selecciona un sector para entrar en sus estantes. Cada ubicación sigue una dirección única.</p><p>Modelo ilustrativo de una planta. Las medidas estiman superficie y capacidad; no validan circulación, carga estructural ni normativa.</p></div></section>';}
  function overview(){return '<section id="warehouse-designer" class="design-saved"><header class="page-heading"><div><div class="eyebrow">Mi almacén / Diseño guardado</div><h1>'+esc(stored.name)+'</h1><p>Tu distribución, de la vista general al detalle de cada estante.</p></div><div class="actions"><button class="btn" data-action="design" type="button">Editar diseño</button><button class="btn btn-primary" data-action="operation-demo" type="button">Probar operación de ejemplo</button></div></header>'+metrics()+preview()+'<div class="design-footnote"><p><b>El espacio ya está definido.</b> Explora sectores y estantes o vuelve al diseñador para cambiar su capacidad.</p><p>La operación de ejemplo utiliza su propio catálogo y plano. La conexión del optimizador con este diseño es la siguiente etapa.</p></div></section>';}
  function plan(config,sectorId,selected,mini=false){
    const s=M.summary(config),sec=M.sectors(config).find(x=>x.id===sectorId),wide=s.overview&&!sec;
    const e=sec?{x:sec.x-sec.width/2-1.5,z:sec.z-sec.depth/2-2,w:sec.width+3,d:sec.depth+4}:{x:-s.width/2,z:-s.depth/2,w:s.width,d:s.depth};
    const nodes=wide||mini?M.runs(config):M.racks(config,sectorId);
    const rects=nodes.map(r=>{const id=wide?r.sectorId:r.id;return '<g '+(mini?'':'data-design-'+(wide?'sector':'rack')+'="'+id+'" class="design-plan-item '+(selected===id?'selected':'')+'" role="button" tabindex="0" aria-label="'+(wide?'Entrar al sector ':'Estante ')+id+'"')+'><rect transform="translate('+(r.x-e.x)+' '+(r.z-e.z)+') rotate('+(-r.rotation*180/Math.PI)+')" x="'+(-r.w/2)+'" y="'+(-r.d/2)+'" width="'+r.w+'" height="'+r.d+'" '+(mini?'fill="currentColor"':'')+'/><title>'+id+'</title></g>';}).join('');
    const roads=M.paths(config,{x:e.x+e.w/2,z:e.z+e.d/2,width:e.w,depth:e.d}).map(p=>'<path d="M'+(p.points[0].x-e.x)+' '+(p.points[0].z-e.z)+' L'+(p.points[1].x-e.x)+' '+(p.points[1].z-e.z)+'" fill="none" stroke="'+(mini?'currentColor':'var(--accent)')+'" stroke-width="'+p.width+'" opacity=".18"/>').join('');
    const labels=wide&&!mini?M.sectors(config).filter((s,i)=>i%Math.max(1,Math.ceil(M.sectors(config).length/100))===0).map(s=>'<g data-design-sector="'+s.id+'" class="design-plan-sector-label" role="button" tabindex="0" aria-label="Entrar al sector '+s.id+'"><text x="'+(s.x-e.x)+'" y="'+(s.z-e.z)+'" font-size="'+Math.min(s.width/5,s.depth/4,3)+'">'+s.id+'</text></g>').join(''):'';
    return '<svg viewBox="0 0 '+e.w+' '+e.d+'" '+(mini?'aria-hidden="true"':'role="group" aria-label="Plano '+typeName(config)+(sec?' · '+sec.id:'')+'"')+'><rect x=".1" y=".1" width="'+(e.w-.2)+'" height="'+(e.d-.2)+'" class="design-plan-floor"/>'+roads+rects+labels+(!sec&&!mini?'<path d="M1 '+(e.d-5)+' H'+(e.w-1)+'" class="design-plan-dispatch"/><text class="design-plan-dispatch-label" x="'+e.w/2+'" y="'+(e.d-1.7)+'" font-size="'+Math.min(e.w/30,2)+'">EMPAQUE / SALIDA</text>':'')+'</svg>';
  }
  function mount({readOnly=false,onSave=()=>{},toast=()=>{}}={}){
    const root=document.getElementById('warehouse-designer');if(!root)return null;
    const $=id=>root.querySelector('#'+id);let config={...(readOnly?stored:draft)},sector=null,selected=null,view='3d',scene=null,timer=null,alive=true;
    const form=$('design-form');
    try{scene=window.KbitLayout3D.create($('design-webgl'),{onSector:setSector,onRack:selectRack});}catch{view='plan';$('design-webgl').replaceChildren();toast('Mostrando el plano 2D. La vista 3D no está disponible en este dispositivo.');}
    function status(){if(readOnly)return;const clean=stored&&equal(config,stored);$('design-save-state').textContent=clean?'Guardado':'Cambios sin guardar';root.querySelector('[data-design-restore]').disabled=!stored;}
    function fill(){
      if(!form)return;
      for(const key of Object.keys(M.limits))if(key!=='sides')form.elements.namedItem(key).value=config[key];
      $('design-name').value=config.name;form.querySelectorAll('[name=sides]').forEach(el=>el.checked=Number(el.value)===config.sides);root.querySelectorAll('[data-design-template]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.designTemplate===config.template)));$('design-config-label').textContent=typeName(config);
      for(const [key,[label,help]] of Object.entries(fieldText(config))){const group=root.querySelector('[data-design-field="'+key+'"]');group.querySelector('label').textContent=label;group.querySelector('small').textContent=help;group.querySelectorAll('button').forEach(button=>button.setAttribute('aria-label',(button.dataset.direction==='1'?'Aumentar ':'Reducir ')+label.toLowerCase()));}
      const isV=config.geometry==='flying-v'||config.geometry==='fishbone';root.querySelector('.design-geometry-fields').hidden=config.geometry==='parallel';root.querySelector('[data-design-field=vDepth]').hidden=!isV;root.querySelector('[data-design-field=angle]').hidden=config.geometry!=='chevron';
      $('design-geometry-note').textContent=({parallel:'Todos los pasillos mantienen filas paralelas.', 'flying-v':'El acceso diagonal descuenta los módulos que cruza. La capacidad corresponde a los estantes visibles.',fishbone:'Las cuatro zonas ajustan sus filas al borde de la V. La capacidad corresponde a los estantes que caben.',chevron:'El ángulo abre las dos alas; el ancho y el fondo del edificio se ajustan al conjunto.'})[config.geometry];
    }
    function selectRack(rack){
      selected=rack?.id??null;$('design-rack').value=selected??'';scene?.select(selected);
      $('design-rack-info').textContent=rack?rack.id+' · '+config.levels+' niveles × '+config.positions+' huecos = '+n(rack.locations)+' ubicaciones. Desde '+M.slotCode(config,rack,0,0)+' hasta '+M.slotCode(config,rack,config.levels-1,config.positions-1)+'.':'Selecciona un estante para ver sus ubicaciones.';
      $('design-plan').innerHTML=plan(config,sector,selected);
    }
    function setSector(id){sector=id||null;selected=null;refresh();}
    function refresh(){
      const s=M.summary(config),sectors=M.sectors(config);if(sector&&!sectors.some(x=>x.id===sector))sector=null;
      $('design-total').textContent=n(s.locations);$('design-formula').textContent=n(s.racks)+' estantes × '+config.levels+' niveles × '+config.positions+' huecos';$('design-racks').textContent=n(s.racks);$('design-stat-aisles').textContent=s.aisleCount+' pasillos con estantes';$('design-area').textContent=n(s.area)+' m²';$('design-dimensions').textContent=n(s.width)+' × '+n(s.depth)+' m';$('design-height').textContent=n(s.height)+' m';$('design-stat-levels').textContent=config.levels+' niveles por estante';
      $('design-sector').innerHTML='<option value="">Almacén completo · '+n(sectors.length)+(sectors.length===1?' sector':' sectores')+'</option>'+sectors.map(sec=>'<option value="'+sec.id+'">'+sec.id+' · '+zoneName(sec.zone)+' · '+n(sec.locations)+' ubicaciones</option>').join('');$('design-sector').value=sector??'';
      const wide=s.overview&&!sector,visible=wide?[]:M.racks(config,sector);$('design-rack').disabled=wide;$('design-rack').innerHTML='<option value="">'+(wide?'Entra a un sector para ver sus estantes':'Selecciona un estante…')+'</option>'+visible.map(r=>'<option value="'+r.id+'">'+r.id+' · '+r.locations+' ubicaciones</option>').join('');
      if(!visible.some(r=>r.id===selected))selected=null;
      $('design-scene-title').textContent=sector?'Sector '+sector:'Almacén completo';$('design-scale-label').textContent=typeName(config).toUpperCase()+' / '+(sector?sector:(wide?'VISTA POR SECTORES':'VISTA DE ESTANTES'));$('design-view-note').textContent=wide?'Selecciona un sector para entrar.':'Cajas ilustrativas · capacidad en el tablero';
      $('design-rack-info').textContent='Selecciona un estante para ver sus ubicaciones.';
      try{scene?.update(config,sector);}catch{scene?.destroy();scene=null;view='plan';toast('Continuamos en el plano 2D.');}
      if(selected)selectRack(visible.find(r=>r.id===selected));else $('design-plan').innerHTML=plan(config,sector,selected);
      showView(view);status();
    }
    function showView(next){view=scene?next:'plan';$('design-webgl').hidden=view!=='3d';$('design-plan').hidden=view!=='plan';root.querySelector('.design-camera').hidden=view!=='3d';root.querySelectorAll('[data-design-view]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.designView===view)));}
    function read(updatePreview=true){
      const candidate={...config,name:$('design-name').value};for(const key of Object.keys(M.limits))candidate[key]=key==='sides'?Number(form.querySelector('[name=sides]:checked').value):Number(form.elements.namedItem(key).value);
      try{for(const key of Object.keys(M.limits)){if(key==='sides')continue;const input=form.elements.namedItem(key);if(!input.validity.valid){input.setAttribute('aria-invalid','true');throw new Error(input.labels[0].textContent+': usa un valor entre '+input.min+' y '+input.max+'.');}input.removeAttribute('aria-invalid');}const next=M.normalize(candidate);M.summary(next);config=next;draft={...config};$('design-error').hidden=true;if(updatePreview)refresh();return true;}catch(error){$('design-error').textContent=error.message;$('design-error').hidden=false;return false;}
    }
    function save(event){event?.preventDefault();clearTimeout(timer);if(!read())return;try{localStorage.setItem(KEY,JSON.stringify(config));stored={...config};status();toast('Diseño guardado. Ya aparece en Mi almacén.');onSave();}catch{toast('No se pudo guardar. Revisa el almacenamiento del navegador.');}}
    function click(event){
      const target=event.target.closest('button,[data-design-rack],[data-design-sector]');if(!target||!root.contains(target))return;
      if(target.hasAttribute('data-design-template')){clearTimeout(timer);if(!read(false))return;try{const next=M.normalize({...config,template:target.dataset.designTemplate,geometry:target.dataset.designTemplate});M.summary(next);config=next;draft={...config};sector=null;selected=null;$('design-error').hidden=true;fill();refresh();}catch(error){toast(error.message);}}
      if(target.hasAttribute('data-design-step')){const input=form.elements.namedItem(target.dataset.designStep);input.value=Number((Math.max(Number(input.min),Math.min(Number(input.max),Number(input.value)+Number(target.dataset.direction)*Number(input.step)))).toFixed(2));read();}
      if(target.hasAttribute('data-design-view'))showView(target.dataset.designView);
      if(target.hasAttribute('data-design-camera'))scene?.preset(target.dataset.designCamera);
      if(target.hasAttribute('data-design-zoom'))scene?.zoom(Number(target.dataset.designZoom));
      if(target.hasAttribute('data-design-all'))setSector(null);
      if(target.hasAttribute('data-design-sector'))setSector(target.dataset.designSector);
      if(target.hasAttribute('data-design-rack'))selectRack(M.racks(config,sector).find(r=>r.id===target.dataset.designRack));
      if(target.hasAttribute('data-design-save'))save();
      if(target.hasAttribute('data-design-restore')&&stored){clearTimeout(timer);config={...stored};draft={...stored};sector=null;selected=null;fill();$('design-error').hidden=true;refresh();toast('Diseño guardado restaurado.');}
    }
    const input=()=>{clearTimeout(timer);timer=setTimeout(()=>{if(alive)read();},160);};
    const change=event=>{if(event.target.id==='design-sector')setSector(event.target.value);if(event.target.id==='design-rack')selectRack(M.racks(config,sector).find(r=>r.id===event.target.value));};
    const keydown=e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-design-rack],[data-design-sector]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}};
    root.addEventListener('click',click);root.addEventListener('change',change);root.addEventListener('keydown',keydown);form?.addEventListener('input',input);form?.addEventListener('submit',save);fill();refresh();
    return {destroy(){if(form){clearTimeout(timer);read(false);}alive=false;scene?.destroy();root.removeEventListener('click',click);root.removeEventListener('change',change);root.removeEventListener('keydown',keydown);form?.removeEventListener('input',input);form?.removeEventListener('submit',save);}};
  }
  window.KbitDesigner={page,overview,mount,plan,saved:()=>stored?{...stored}:null};
})();
